// Написан autotest-writer вручную (нужна проверка сетевых запросов). spec: .qa/e2e/specs/date-now.md 4.1; кейс .qa/tests/date-now/DN-11.
// reg5 (0009, free): недельный Date Now израсходован 12.11 14:32 (следующий 19.11). Перед нажатием тест проверяет строку
// «אפשר שוב …» в шите; нет её — квота обновилась → падение «ОКРУЖЕНИЕ», ничего не нажимается (иначе потратит неделю).
// Тексты — со скринов r10 (r10-1e665f-*). Не проверен на живой странице — проверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import * as fs from 'fs';
import * as path from 'path';
import { saveSession } from '../_shared/session';

const PILL = 'שיתוף מיקום פעיל';
const OFF = 'שיתוף מיקום כבוי';

async function setupReg5(page: import('@playwright/test').Page) {
  await page.setViewportSize({ width: 390, height: 844 });
  const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
  const origin = new URL(process.env.QA_BASE_URL || cfg.baseUrl).origin;
  await page.context().grantPermissions(['geolocation'], { origin });
  await page.context().setGeolocation({ latitude: 32.0809, longitude: 34.7806, accuracy: 10 });
}

async function openMapOff(page: import('@playwright/test').Page) {
  await page.goto('/map');
  await expect(page.getByText(OFF).or(page.getByText(PILL)).first()).toBeVisible({ timeout: 30_000 });
}

// Выключить шаринг (пилюля → «כיבוי שיתוף מיקום»), если включён.
async function ensureSharingOff(page: import('@playwright/test').Page) {
  await openMapOff(page);
  if (await page.getByText(OFF).isVisible()) return;
  await page.getByText(PILL).click();
  await page.getByText('כיבוי שיתוף מיקום', { exact: true }).click();
  await expect(page.getByText(OFF)).toBeVisible();
}

test.describe('דייט עכשיו — free с исчерпанной квотой', () => {
  test.describe.configure({ timeout: 150_000 });

  test('free с исчерпанной квотой: «להפעיל עם שיתוף מיקום» → Premium-окно, нет «שיתוף מיקום פעיל» и успешного set_date_now; после закрытия и обновления — «כבוי» @iphone @data (#1e665f)', async ({ asUser }) => {
    const p = await asUser('reg5');
    const okWrites: string[] = [];
    p.on('response', (r) => {
      const req = r.request();
      const u = r.url();
      if (!r.ok() || ['GET', 'HEAD', 'OPTIONS'].includes(req.method())) return;
      if (u.includes('/rpc/set_date_now')) okWrites.push(`set_date_now ${r.status()}`);
      // share_location:true с немедленным откатом допустим по исправлению («выключается обратно») — проверяем итоговое состояние.
    });
    try {
      await setupReg5(p);
      await ensureSharingOff(p);

      // Шит «פנוי/ה לדייט עכשיו?» и проверка квоты ДО нажатия.
      await p.getByRole('button', { name: /דייט עכשיו/ }).first().click();
      const sheet = p.getByText('פנוי/ה לדייט עכשיו?');
      await expect(sheet).toBeVisible();
      await expect(
        p.getByText(/במסלול החינמי פעם ב-7 ימים\s*•\s*אפשר שוב/),
        'ОКРУЖЕНИЕ: у reg5 недельная квота Date Now не израсходована (нет «אפשר שוב …») — не нажимаем, иначе потратим неделю. Израсходовать вручную с разрешения пользователя или ждать.',
      ).toBeVisible({ timeout: 15_000 });

      // «להפעיל עם שיתוף מיקום» → Premium-окно.
      await p.getByRole('button', { name: /להפעיל עם שיתוף/ }).click();
      await expect(p.getByText('לשדרג ל-Premium').first()).toBeVisible({ timeout: 15_000 });
      await expect(p.getByText(PILL)).toHaveCount(0);

      // Закрыть окно и шит.
      await p.getByRole('button', { name: /סגירה|close|✕/i }).first().click().catch(() => {});
      const notNow = p.getByRole('button', { name: 'לא עכשיו' });
      if (await notNow.first().isVisible()) await notNow.first().click();
      if (await notNow.first().isVisible()) await notNow.first().click();
      await expect(p.getByText(PILL)).toHaveCount(0);

      // После обновления — выключен, плашки Date Now нет.
      await openMapOff(p);
      await expect(p.getByText(OFF)).toBeVisible();
      await expect(p.getByText(PILL)).toHaveCount(0);
      await expect(p.getByText(/דייט עכשיו\s*•\s*\d+:\d{2}/)).toHaveCount(0);
      expect(okWrites, 'не должно быть успешного set_date_now').toEqual([]);
    } finally {
      await ensureSharingOff(p).catch(() => {});
      await saveSession(p, 'reg5');
    }
  });
});
